import 'dotenv/config';
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

// Keep one model definition; commit the derived PostgreSQL schema for migrations.
const schema = readFileSync('prisma/schema.prisma', 'utf8');
writeFileSync(
  'prisma/schema.postgresql.prisma',
  '// Generated by scripts/generate-client.mjs; edit schema.prisma instead.\n' +
    schema.replace('provider = "sqlite"', 'provider = "postgresql"'),
);
const result = spawnSync(process.execPath, ['node_modules/prisma/build/index.js', 'generate'], {
  stdio: 'inherit',
  env: process.env,
});
process.exit(result.status ?? 1);
